    # Worker defaults missing legacy mode to all
    # Unknown job mode means missing or None, and such jobs stay included for every filter
    # excludes known mismatches, preserves input order and input objects

    # Get the task mode, default to "all" if missing or None (legacy mode defaults to all)
    task_mode = task.get("mode") if isinstance(task, dict) else None
    if task_mode is None:
        task_mode = "all"

    result = []
    for job in jobs:
        job_mode = job.get("mode") if isinstance(job, dict) else None

        # Unknown job mode (missing or None) means job stays included for every filter
        if job_mode is None:
            result.append(job)
        else:
            # For task_mode "all", include all jobs
            if task_mode == "all":
                result.append(job)
            # For specific task_mode, include only jobs with matching mode
            elif task_mode == job_mode:
                result.append(job)
